mapper.select:
select id, content, user_id, target_id, type, nick_name, create_time from ich_comment

     and target_id = #{targetId}
     and type = #{type}

order by create_time desc

select c.id, c.content, c.user_id, c.target_id, c.type, c.nick_name, c.create_time,
    case when c.type = 1 then h.title when c.type = 2 then n.title end as target_name
from ich_comment c
left join heritage h on c.type = 1 and c.target_id = h.heritage_id
left join news n on c.type = 2 and c.target_id = n.news_id

     and c.content like concat('%', #{content}, '%')
     and c.type = #{type}
     and c.user_id = #{userId}
     and c.target_id = #{targetId}

order by c.create_time desc

mapper.update:
update ich_comment
content = #{content}, type = #{type},
where id = #{id}
